mapper.select:
		SELECT DISTINCT B.ACCT_NO   as acctNo,
						C.ACCT_NAME as acctName
		FROM stl_fin_product_acct B
		left join STL_CAPACCT_INFO C on B.ACCT_NO = c.ACCT_NO and B.CCY = C.CCY
        left join FIN_PRODUCT fp on fp.FINPROD_ID = B.FINPROD_ID
		WHERE fp.FINPROD_MARKET_ID = #{chlId}
		  and B.ACCT_TYPE=#{capacctType}
		  AND B.CCY = #{ccy}

SELECT DISTINCT B.ACCT_NO as acctNo, B.BUSI_ACCT_NO busiAcctNo, B.CCY CCY, A.ACCT_TYPE acctType, B.ACCT_NAME as acctName, B.OWN_DEPT stockExchangeNo, '1' status, B.ACC_PASS acctPwd, B.TRADE_PASS tradePwd FROM MST_COUNTER_ACCT A, STL_CAPACCT_INFO B
A.COUNTER_ID = #{counterId}
and A.ACCT_TYPE =#{acctType}
AND A.ACCT_NO = B.ACCT_NO AND A.IS_OPEN = '01' /**add by 张年 20190904 交易对手资金账户只能选择启用状态下的账户**/ AND A.CCY = B.CCY
AND A.CCY = #{ccy}

SELECT ACCT_NO id, ACCT_NAME text ,SEQ_NO /* add by songyawei 2020-06-18 */ FROM STL_CAPACCT_INFO
( ACCT_NO LIKE CONCAT('%', CONCAT(#{search}, '%')) OR ACCT_NAME LIKE CONCAT('%', CONCAT(#{search}, '%')) )
and CCY = #{ccy_select}

SELECT
TOTLE_TRADE_ID FROM TRD_FIN_PRODUCT_DEAL_TOTAL WHERE P_TOTLE_TRADE_ID
= #{bizCode}

SELECT
TOTLE_TRADE_ID FROM WFL_TRD_FIN_PRODUCT_DEAL_TOTAL WHERE
P_TOTLE_TRADE_ID = #{bizCode}

select

from STL_CAPACCT_INFO
where ACCT_NO = #{busiAcctNo}
and CCY = #{ccy}
